import os
from flask import Flask, request, abort

app = Flask(__name__)

@app.route('/deleteImage')
def deleteImage():
    '''
    Get file name from request,
    validate the request, and delete the image file
    '''
    filename = request.args.get('filename')

    if not filename:
        return "Filename is required", 400

    # Ensure the filename is safe and within the allowed directory
    allowed_directory = os.path.abspath("images")
    target_path = os.path.abspath(os.path.join(allowed_directory, filename))

    if not target_path.startswith(allowed_directory):
        return "Invalid path", 400

    try:
        os.remove(target_path)
        return f"File {filename} deleted successfully"
    except FileNotFoundError:
        return f"File {filename} not found", 404
    except Exception as e:
        return str(e), 500

if __name__ == "__main__":
    app.run(debug=True)
